import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { PresentService } from '../../../services/present/present.service';
import { DocInfo, PDFAnnotation } from '../../../../pdf/interfaces/pdf.interface';
import { presentSharedLinks, remarkList } from '../../../interfaces/present-linkshare.interface';
import { IconComponent } from '../../../../shared/components/icon/icon.component';

@Component({
  selector: 'link-share',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [IconComponent],
  templateUrl: './link-share.component.html',
  styleUrl: './link-share.component.scss'
})
export class LinkShareComponent {
  @Input() docInfo: DocInfo | null = {} as DocInfo;
  @Input() actionLinkAnnot: PDFAnnotation;

  @Input() isRightClicked: boolean;
  @Output() isRightClickedChange = new EventEmitter<boolean>();
  sharedLinks: presentSharedLinks[] = [];
  remarksList: remarkList[] = [];
  isAlreadyShared: boolean = false;
  type: string;
  isColapsed: boolean = false;
  remarks: any = [];

  isRemarksColapsed: boolean = false;

  remarkIcon: any;
  constructor(private readonly presentService: PresentService, private cdr: ChangeDetectorRef) {
  }

  async ngOnInit() {
    const list = await this.presentService.getPresentLinksSharedBy(this.docInfo?.nPresentid, this.docInfo?.nBundledetailid);
    this.sharedLinks = list[0] || []
    this.remarksList = list[1] || []
    this.remarks = await this.presentService.getRemarks()
    this.cdr.detectChanges();
  }


  ngOnChanges(changes: SimpleChanges): void {
    if (changes["actionLinkAnnot"] && !changes["actionLinkAnnot"].firstChange) {
      this.initDetail()
    }
  }


  initDetail() {

    try {
      this.type = ['F', 'QF'].includes(this.actionLinkAnnot?.linktype) ? 'Fact' : this.actionLinkAnnot?.linktype == 'D' ? 'Doc Link' : 'Web link';
      this.isAlreadyShared = false;
      this.isRemarksColapsed = false;
      this.isColapsed = false;
      if (this.sharedLinks.findIndex(a => a.nAId == this.actionLinkAnnot.nAId) > -1) {
        this.isAlreadyShared = true;
      }
      this.remarkIcon = null;

      const obj = this.remarksList.find(a => a.nAId == this.actionLinkAnnot.nAId)
      if (obj) {
        this.remarkIcon = this.remarks.find(a => a.nCodeid == obj.nRemarkid)?.jOther?.icon;
      }
    } catch (error) {
    }
    this.cdr.detectChanges();
  }


  async shareThisLink(val: boolean) {
    const res = await this.presentService.manageLinkShare(this.docInfo?.nPresentid, this.actionLinkAnnot?.nAId, this.docInfo?.nBundledetailid, val, 'N')
    if (res.msg == 1) {

    }
    if (this.sharedLinks.findIndex(a => a.nAId == this.actionLinkAnnot.nAId) == -1) {
      this.sharedLinks.push({ nAId: this.actionLinkAnnot.nAId, isWithLink: val })
    }

    this.close()

  }

  async unShareHighlight() {
    const res = await this.presentService.manageLinkShare(this.docInfo?.nPresentid, this.actionLinkAnnot?.nAId, this.docInfo?.nBundledetailid, false, 'D')
    if (res.msg == 1) {

    }
    const ind = this.sharedLinks.findIndex(a => a.nAId == this.actionLinkAnnot.nAId);
    if (ind > -1) {
      this.sharedLinks.splice(ind, 1);
    }
    this.close()
  }

  close() {
    this.isAlreadyShared = false;
    this.isColapsed = false;
    this.isRightClicked = false;
    this.isRemarksColapsed = false;
    this.isRightClickedChange.emit(this.isRightClicked)
    this.cdr.detectChanges();
  }


  async setRemark(x) {
    await this.presentService.setRemarkToLink(this.docInfo.nPresentid, this.actionLinkAnnot.nAId, this.docInfo.nBundledetailid, x.nCodeid);
    this.remarkIcon = x.jOther?.icon;
    const ind = this.remarksList.findIndex(a => a.nAId == this.actionLinkAnnot.nAId);
    if (ind > -1) {
      this.remarksList[ind].nRemarkid = x.nCodeid
    } else {
      this.remarksList.push({ nAId: this.actionLinkAnnot.nAId, nRemarkid: x.nCodeid, nPRid: null })
    }
    this.cdr.detectChanges();
  }

}